import { useState } from 'react'
import { Card, EmptyState, Field, Scale, VisibilityBadge } from '@/components/ui'
import { Icon } from '@/design-system/Icon'
import { useT } from '@/i18n'
import type { Profile } from '@/types/domain'
import { clampShare, perceptionGap, roundIdFor, type FairnessAnswer } from './choreMath'
import { addChoreRecord, patchChoreRecord, setChoreVisibility, type ChoreRecord } from './store'

type FairnessRecord = Extract<ChoreRecord, { kind: 'fairness' }>

/**
 * FAIRNESS REVIEW.
 *
 * Both people answer the same two questions about the same month, privately.
 * The report compares each person's own number against the other's estimate of
 * them, in both directions, and stops there. There is no total, no ranking, and
 * no sentence anywhere that concludes who does more — the output is a gap in
 * perception, which is the thing that is actually actionable.
 *
 * Answers are C3_relationship, so they start private. The comparison is only
 * possible once both owners have chosen to open theirs, which is the same
 * consent rule the rest of the app uses rather than a special case.
 */
export function Fairness({
  me,
  profiles,
  records,
}: {
  me: string
  profiles: Profile[]
  records: ChoreRecord[]
}) {
  const t = useT()
  const round = roundIdFor(new Date())
  const answers = records.filter(
    (r): r is FairnessRecord => r.kind === 'fairness' && r.round === round,
  )
  const mine = answers.find((a) => a.profileId === me)
  const theirs = answers.find((a) => a.profileId !== me)

  const [selfShare, setSelfShare] = useState(mine?.selfShare ?? 50)
  const [partnerShare, setPartnerShare] = useState(mine?.partnerShare ?? 50)
  const [heaviness, setHeaviness] = useState<1 | 2 | 3 | 4 | 5>(mine?.heaviness ?? 3)
  const [unseen, setUnseen] = useState(mine?.unseenNote ?? '')
  const [dirty, setDirty] = useState(false)

  const name = (id: string) => profiles.find((p) => p.id === id)?.displayName ?? t('chores.stepNobody')

  async function save() {
    const body = {
      selfShare: clampShare(selfShare),
      partnerShare: clampShare(partnerShare),
      heaviness,
      unseenNote: unseen.trim() || undefined,
    }
    if (mine) await patchChoreRecord(mine.id, body)
    else await addChoreRecord(me, 'C3_relationship', { kind: 'fairness', round, profileId: me, ...body })
    setDirty(false)
  }

  const report =
    mine && theirs ? perceptionGap(toAnswer(mine), toAnswer(theirs)) : null

  return (
    <Card title={t('chores.fairness')} icon="mentalload" hint={t('chores.fairnessHint')}>
      <p className="card__hint">{t('chores.fair.round', { round })}</p>

      <ShareSlider
        label={t('chores.fair.selfShare')}
        value={selfShare}
        onChange={(v) => {
          setSelfShare(v)
          setDirty(true)
        }}
      />
      <ShareSlider
        label={t('chores.fair.partnerShare')}
        value={partnerShare}
        onChange={(v) => {
          setPartnerShare(v)
          setDirty(true)
        }}
      />
      <Scale
        legend={t('chores.fair.heaviness')}
        value={heaviness}
        onChange={(v) => {
          setHeaviness(v)
          setDirty(true)
        }}
        lowLabel={t('chores.fair.low')}
        highLabel={t('chores.fair.high')}
      />
      <Field label={t('chores.fair.unseen')} hint={t('chores.fair.unseenHint')}>
        {(p) => (
          <textarea
            {...p}
            rows={2}
            value={unseen}
            onChange={(e) => {
              setUnseen(e.target.value)
              setDirty(true)
            }}
          />
        )}
      </Field>
      <button className="btn btn--block" onClick={save} disabled={!dirty && !!mine}>
        {t('chores.fair.save')}
      </button>

      {mine && (
        <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
          <VisibilityBadge visibility={mine.visibility} />
          {mine.visibility !== 'shared' ? (
            <button
              className="btn btn--soft btn--sm"
              onClick={() => setChoreVisibility(mine.id, me, 'shared')}
            >
              <Icon name="shared" size={16} /> {t('chores.fair.share')}
            </button>
          ) : (
            <span className="card__hint">{t('chores.fair.shareHint')}</span>
          )}
        </div>
      )}
      {mine && mine.visibility !== 'shared' && <p className="card__hint">{t('chores.fair.saved')}</p>}

      {report ? (
        <div className="stack stack--tight" style={{ marginTop: 'var(--space-2)' }}>
          {report.rows.map((row) => (
            <p key={row.aboutProfileId} className="banner">
              {t('chores.fair.gapAbout', {
                name: name(row.aboutProfileId),
                self: row.selfShare,
                other: row.partnerEstimate,
                gap: row.gap,
              })}
            </p>
          ))}
          <p>{t(report.toneKey)}</p>
          {answers
            .filter((a) => a.unseenNote)
            .map((a) => (
              <p key={a.id} className="card__hint">
                <strong>{t('chores.fair.unseenFrom', { name: name(a.profileId) })}:</strong>{' '}
                {a.unseenNote}
              </p>
            ))}
          <p className="disclaimer">{t('chores.fair.noVerdict')}</p>
        </div>
      ) : (
        <EmptyState
          icon="consent"
          title={t('chores.fair.waiting')}
          hint={t('chores.fair.waitingHint')}
        />
      )}
    </Card>
  )
}

function toAnswer(r: FairnessRecord): FairnessAnswer {
  return {
    profileId: r.profileId,
    // Clamped on the way out too: a restored or hand-edited row must not push
    // the gap past 100 points.
    selfShare: clampShare(r.selfShare),
    partnerShare: clampShare(r.partnerShare),
    heaviness: r.heaviness,
  }
}

/** Native range input — no library, works with a keyboard, reads as a slider. */
function ShareSlider({
  label,
  value,
  onChange,
}: {
  label: string
  value: number
  onChange: (v: number) => void
}) {
  const t = useT()
  return (
    <Field label={label}>
      {(p) => (
        <div className="row" style={{ gap: 10 }}>
          <input
            {...p}
            type="range"
            min={0}
            max={100}
            step={5}
            value={value}
            onChange={(e) => onChange(Number(e.target.value))}
            style={{ flex: 1 }}
          />
          <output style={{ minWidth: '3.5em', textAlign: 'right', fontWeight: 700 }}>
            {t('chores.fair.percent', { n: value })}
          </output>
        </div>
      )}
    </Field>
  )
}
