/**
 * Chore ownership maths.
 *
 * No user-facing copy in here (CLAUDE.md §i18n) — anything the UI must say comes
 * back as a message key. Everything is pure so the awkward parts (capacity
 * weighting, survival mode, perception gap) are testable without a database.
 */

/**
 * Outcome domains. The brief names five; `rumah` is the sixth because the
 * Indonesian templates that ship with this module (token listrik, iuran RT,
 * sampah) are household-utility work and do not belong in a kitchen.
 */
export const DOMAIN_KEYS = [
  'dapur',
  'laundry',
  'kendaraan',
  'kesehatan',
  'keluarga_besar',
  'rumah',
] as const
export type DomainKey = (typeof DOMAIN_KEYS)[number]

/**
 * Domains Minimum Survival Mode never switches off. "We are both drowning" must
 * not turn into a missed dose or a missed appointment — that is the one place
 * where pausing has a real-world consequence.
 */
export const ALWAYS_KEPT_DOMAINS: readonly DomainKey[] = ['kesehatan']

/**
 * The full cycle. `notice` and `plan` overlap with the existing `MentalLoadType`;
 * `conceive` (working out what "handled" would even look like), `decide`
 * (picking between options and owning the choice), and `verify` (checking it
 * actually landed) are the invisible three that the task model never had.
 */
export const CYCLE_STEPS = ['notice', 'conceive', 'plan', 'decide', 'execute', 'verify'] as const
export type CycleStep = (typeof CYCLE_STEPS)[number]

/** Who carries each step. Missing key = nobody has claimed it yet. */
export type CycleOwners = Partial<Record<CycleStep, string>>

export const CAPACITY_STATES = [
  'normal',
  'sibuk',
  'sakit',
  'dinas',
  'hamil',
  'pemulihan',
] as const
export type CapacityState = (typeof CAPACITY_STATES)[number]

/**
 * Rough share of a normal week someone has left in each state, used only to
 * order a *suggestion* for who takes the next thing. It is not a measurement of
 * anyone's effort and never feeds a total or a comparison.
 *
 * ponytail: flat constants, deliberately. Real capacity varies per person and
 * per week; if this ever needs to be honest per couple, make it a per-profile
 * multiplier the owner sets themselves rather than adding more states here.
 */
export const CAPACITY_WEIGHT: Record<CapacityState, number> = {
  normal: 1,
  sibuk: 0.6,
  hamil: 0.7,
  dinas: 0.4,
  pemulihan: 0.35,
  sakit: 0.25,
}

export interface Candidate {
  profileId: string
  state: CapacityState
  /** Chore tasks currently open and accountable to this person. */
  openCount: number
}

/**
 * Suggests who has the most room right now. Deterministic: ties break on
 * profileId so the same input never renders two different names.
 *
 * `openCount + 1` rather than `openCount` so that with an empty board the
 * capacity state still decides — otherwise every score is 0 and the person who
 * said "sakit" is as likely to be suggested as anyone.
 */
export function suggestOwner(candidates: Candidate[]): string | null {
  if (candidates.length === 0) return null
  const scored = candidates.map((c) => ({
    id: c.profileId,
    score: (c.openCount + 1) / CAPACITY_WEIGHT[c.state],
  }))
  scored.sort((a, b) => a.score - b.score || a.id.localeCompare(b.id))
  return scored[0]!.id
}

export interface DefinitionOfDone {
  minimum: string
  lengkap: string
  excluded: string
}

export type DodStateKey = 'chores.dod.empty' | 'chores.dod.partial' | 'chores.dod.full'

/**
 * "Full" requires all three fields, including what is *not* included. Naming the
 * exclusion is the half people skip, and it is the half the arguments are about.
 */
export function dodState(dod?: Partial<DefinitionOfDone>): DodStateKey {
  const filled = (['minimum', 'lengkap', 'excluded'] as const).filter((k) =>
    (dod?.[k] ?? '').trim(),
  ).length
  if (filled === 0) return 'chores.dod.empty'
  return filled === 3 ? 'chores.dod.full' : 'chores.dod.partial'
}

export function cycleCoverage(owners?: CycleOwners): {
  covered: CycleStep[]
  missing: CycleStep[]
} {
  const covered = CYCLE_STEPS.filter((s) => (owners?.[s] ?? '').trim() !== '')
  return { covered, missing: CYCLE_STEPS.filter((s) => !covered.includes(s)) }
}

export interface SurvivalSplit<T> {
  keep: T[]
  pause: T[]
}

/** Splits chore work into what still runs and what waits. Nothing is deleted. */
export function survivalPlan<T extends { domainKey?: string }>(
  tasks: readonly T[],
  keptDomainKeys: readonly string[],
): SurvivalSplit<T> {
  const always = ALWAYS_KEPT_DOMAINS as readonly string[]
  const keep: T[] = []
  const pause: T[] = []
  for (const task of tasks) {
    const key = task.domainKey ?? ''
    if (keptDomainKeys.includes(key) || always.includes(key)) keep.push(task)
    else pause.push(task)
  }
  return { keep, pause }
}

export interface FairnessAnswer {
  profileId: string
  /** 0–100. How much of the load this person feels they carry. */
  selfShare: number
  /** 0–100. How much they think their partner carries. */
  partnerShare: number
  heaviness: 1 | 2 | 3 | 4 | 5
}

export interface GapRow {
  aboutProfileId: string
  selfShare: number
  /** What the *other* person estimated for this person. */
  partnerEstimate: number
  gap: number
}

export type GapToneKey = 'chores.gap.aligned' | 'chores.gap.some' | 'chores.gap.wide'

export interface GapReport {
  rows: GapRow[]
  widest: number
  toneKey: GapToneKey
}

/**
 * Reports how differently the two people see the same household — never who is
 * right. The output is symmetric by construction: one row per person, each
 * comparing their own number against the other's estimate of them.
 *
 * ponytail: 10 / 25 points are picked thresholds, not measured ones. They only
 * choose which sentence appears; the numbers are always shown as well.
 */
export function perceptionGap(a: FairnessAnswer, b: FairnessAnswer): GapReport {
  const rows: GapRow[] = [
    {
      aboutProfileId: a.profileId,
      selfShare: a.selfShare,
      partnerEstimate: b.partnerShare,
      gap: Math.abs(a.selfShare - b.partnerShare),
    },
    {
      aboutProfileId: b.profileId,
      selfShare: b.selfShare,
      partnerEstimate: a.partnerShare,
      gap: Math.abs(b.selfShare - a.partnerShare),
    },
  ]
  const widest = Math.max(...rows.map((r) => r.gap))
  const toneKey: GapToneKey =
    widest <= 10 ? 'chores.gap.aligned' : widest <= 25 ? 'chores.gap.some' : 'chores.gap.wide'
  return { rows, widest, toneKey }
}

/** Reviews are grouped by calendar month, so both people land in the same round. */
export function roundIdFor(date: Date): string {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`
}

/** Keeps a slider or a restored record inside 0–100 whatever it claims to be. */
export function clampShare(n: number): number {
  if (!Number.isFinite(n)) return 0
  return Math.min(100, Math.max(0, Math.round(n)))
}
