import { db, logAudit, newEnvelope, patch, setVisibility } from '@/db/db'
import { useOwned } from '@/db/hooks'
import type { DataClass, Envelope, Owned, Visibility } from '@/types/domain'
import type { CapacityState, CycleOwners, DefinitionOfDone, DomainKey } from './choreMath'
import type { Task } from '@/types/domain'

/**
 * Storage for chore ownership.
 *
 * Lives in the real `domains` store (db.ts v4), so it gets everything the shared
 * plumbing gives every other store: `newEnvelope()` on write, `useOwned()` (and
 * therefore `canRead()`) on read, owner-only visibility changes, and — the part
 * that actually mattered — inclusion in `OWNED_STORES`, so a capacity note
 * (C4_health) is exported with a backup and revoked at uncoupling.
 */

export const CHORES = 'domains' as const

export type ChoreRecord = Owned<
  | {
      kind: 'domain'
      domainKey: DomainKey
      /** Exactly one person owns the outcome. Helpers are still helpers. */
      accountableProfileId: string
      note?: string
    }
  | {
      kind: 'capacity'
      profileId: string
      state: CapacityState
      /** Free-form ISO date the person expects to be back at normal. Optional. */
      until?: string
      note?: string
    }
  | {
      kind: 'survival'
      startedAt: string
      endedAt?: string
      keptDomainKeys: DomainKey[]
    }
  | {
      kind: 'fairness'
      /** `yyyy-MM` — both partners answer into the same round. */
      round: string
      profileId: string
      selfShare: number
      partnerShare: number
      heaviness: 1 | 2 | 3 | 4 | 5
      unseenNote?: string
    }
>

export type ChoreKind = ChoreRecord['kind']

/** Live read through the one gate. */
export function useChoreRecords(viewerProfileId: string | undefined): ChoreRecord[] | undefined {
  return useOwned<ChoreRecord>(CHORES, viewerProfileId)
}

type Body<K extends ChoreKind> = Omit<Extract<ChoreRecord, { kind: K }>, keyof Envelope>

export async function addChoreRecord<K extends ChoreKind>(
  actorProfileId: string,
  dataClass: DataClass,
  body: Body<K> & { kind: K },
): Promise<string> {
  // Spreading an envelope over one arm of a discriminated union is something TS
  // cannot narrow; `Body<K>` above is what actually keeps call sites honest.
  const row = { ...newEnvelope(actorProfileId, dataClass), ...body } as unknown as ChoreRecord
  await db.domains.add(row)
  // Summary names the kind only — an audit log must not become a second copy of
  // the data (TRUST-03).
  await logAudit({
    actorProfileId,
    action: 'create',
    objectStore: 'domains',
    objectId: row.id,
    summary: `${body.kind} dibuat`,
  })
  return row.id
}

/** Partial update on a discriminated union — `patch()` owns the one cast. */
export async function patchChoreRecord(id: string, changes: Record<string, unknown>): Promise<void> {
  await patch(CHORES, id, changes)
}

/** Owner-only, and audited. A co-owner widening health data is the exact thing
 *  the privacy model exists to prevent — `setVisibility()` is what enforces it. */
export async function setChoreVisibility(
  id: string,
  actorProfileId: string,
  visibility: Visibility,
): Promise<void> {
  await setVisibility(CHORES, id, actorProfileId, visibility)
}

/**
 * A chore is an ordinary task with ownership attached, so it stays in the real
 * `tasks` store: gated, backed up, unpaired, and still counted by the mental
 * load table on Kehidupan. The extra fields are additive, which is why nothing
 * in `db.ts` had to change for them.
 */
export type ChoreTask = Task & {
  domainKey?: DomainKey
  dod?: Partial<DefinitionOfDone>
  cycleOwners?: CycleOwners
}
