import { useState } from 'react'
import { Card, EmptyState, Field, PARTNER_VISIBILITY_OPTIONS, Sheet, VisibilityBadge } from '@/components/ui'
import { Icon } from '@/design-system/Icon'
import { useSession } from '@/app/session'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { MENTAL_LOAD_TYPES, type MentalLoadType, type Profile, type Visibility } from '@/types/domain'
import { useI18n, useT, baseLocale } from '@/i18n'
import { fmtDate, mentalLoadLabel, whenLabel } from '@/i18n/format'
import {
  CAPACITY_STATES,
  CYCLE_STEPS,
  DOMAIN_KEYS,
  cycleCoverage,
  dodState,
  roundIdFor,
  suggestOwner,
  survivalPlan,
  type CapacityState,
  type CycleStep,
  type DomainKey,
} from './choreMath'
import { CHORE_TEMPLATES, type TemplateId } from './templates'
import {
  addChoreRecord,
  patchChoreRecord,
  setChoreVisibility,
  useChoreRecords,
  type ChoreRecord,
  type ChoreTask,
} from './store'
import { Fairness } from './Fairness'

type DomainRow = Extract<ChoreRecord, { kind: 'domain' }>
type CapacityRow = Extract<ChoreRecord, { kind: 'capacity' }>
type SurvivalRow = Extract<ChoreRecord, { kind: 'survival' }>

/**
 * Urusan rumah — domain ownership, the full notice→verify cycle, a written
 * definition of done, capacity, survival mode, and a perception review.
 *
 * The chores themselves stay in the shared `tasks` store with three extra
 * fields, so they keep showing up on Kehidupan and in the mental-load table
 * instead of becoming a second, parallel to-do list.
 */
export default function Chores() {
  const { t, locale: uiLocale } = useI18n()
  // `dwi` is a display mode, not a language — formatters and data tables
  // take the real one.
  const locale = baseLocale(uiLocale)
  const { profile, profiles } = useSession()
  const me = profile?.id
  const records = useChoreRecords(me) ?? []
  const tasks = useOwned<ChoreTask>('tasks', me) ?? []
  const [sheetOpen, setSheetOpen] = useState(false)

  if (!profile || !me) return null

  const choreTasks = tasks.filter((x) => x.domainKey !== undefined)
  const openTasks = choreTasks.filter((x) => x.status !== 'done')
  const doneTasks = choreTasks.filter((x) => x.status === 'done')

  const survival = records.find((r): r is SurvivalRow => r.kind === 'survival' && !r.endedAt)
  const split = survivalPlan(openTasks, survival?.keptDomainKeys ?? [])
  const running = survival ? split.keep : openTasks
  const paused = survival ? split.pause : []

  const capacityOf = (profileId: string): CapacityRow | undefined =>
    records
      .filter((r): r is CapacityRow => r.kind === 'capacity' && r.profileId === profileId)
      .sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0]

  // A partner who has not opened their capacity is counted as normal. That is a
  // guess and the UI says so — the alternative is inferring something about
  // someone's health from the absence of a record, which is worse.
  const suggestedId = suggestOwner(
    profiles.map((p) => ({
      profileId: p.id,
      state: capacityOf(p.id)?.state ?? 'normal',
      openCount: openTasks.filter((x) => x.accountableProfileId === p.id).length,
    })),
  )
  const nameOf = (id: string | undefined) =>
    profiles.find((p) => p.id === id)?.displayName ?? t('chores.noOwner')

  const myCapacity = capacityOf(me)
  const partner = profiles.find((p) => p.id !== me)
  const partnerCapacity = partner ? capacityOf(partner.id) : undefined

  return (
    <div className="stack">
      <h1>{t('chores.title')}</h1>
      <p className="card__hint">{t('chores.intro')}</p>

      {survival && paused.length > 0 && (
        <p className="banner banner--warn" role="status">
          <Icon name="info" size={18} /> {t('chores.survivalPaused', { n: paused.length })}
        </p>
      )}

      <Card title={t('chores.capacity')} icon="health" hint={t('chores.capacityHint')}>
        <CapacityForm key={myCapacity?.id ?? 'new'} me={me} record={myCapacity} />
        <p className="disclaimer">{t('chores.capacityPrivate')}</p>

        <h3 style={{ fontSize: 14, marginTop: 'var(--space-2)' }}>{t('chores.capacityPartner')}</h3>
        {partner && partnerCapacity ? (
          <p className="card__hint">
            <strong>{partner.displayName}</strong> · {t(`chores.cap.${partnerCapacity.state}` as const)}
            {partnerCapacity.until
              ? ` · ${t('chores.capacityUntilLabel', { date: fmtDate(partnerCapacity.until, 'd MMM', locale) })}`
              : ''}
            {partnerCapacity.note ? ` · ${partnerCapacity.note}` : ''}
          </p>
        ) : (
          <p className="card__hint">{t('chores.capacityPartnerHidden')}</p>
        )}

        {suggestedId && profiles.length > 1 && (
          <p className="card__hint">{t('chores.suggested', { name: nameOf(suggestedId) })}</p>
        )}
        <p className="disclaimer">{t('chores.capacityCaveat')}</p>
      </Card>

      <SurvivalCard me={me} survival={survival} pausedCount={paused.length} />

      <Card title={t('chores.domains')} icon="mentalload" hint={t('chores.domainsHint')}>
        <ul className="list">
          {DOMAIN_KEYS.map((key) => {
            const row = records.find((r): r is DomainRow => r.kind === 'domain' && r.domainKey === key)
            const count = openTasks.filter((x) => x.domainKey === key).length
            return (
              <li key={key} className="list__item">
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{t(`chores.domain.${key}` as const)}</strong>
                  <span className="card__hint">
                    {row ? nameOf(row.accountableProfileId) : t('chores.noOwner')} ·{' '}
                    {t('chores.openCount', { n: count })}
                  </span>
                  {row?.note && <span className="card__hint">{row.note}</span>}
                </span>
                {/* flex:none so the select keeps its width and the label above
                    wraps to its own line at 320 px instead of being crushed. */}
                <div style={{ flex: 'none', minWidth: 140 }}>
                  <Field label={t('chores.domainOwner')}>
                    {(p) => (
                      <select
                        {...p}
                        value={row?.accountableProfileId ?? ''}
                        onChange={(e) => setDomainOwner(me, key, row, e.target.value)}
                      >
                        <option value="">{t('chores.noOwner')}</option>
                        {profiles.map((p2) => (
                          <option key={p2.id} value={p2.id}>
                            {p2.displayName}
                          </option>
                        ))}
                      </select>
                    )}
                  </Field>
                </div>
              </li>
            )
          })}
        </ul>
      </Card>

      <Card
        title={t('chores.tasks')}
        icon="tasks"
        hint={t('chores.tasksHint')}
        action={
          <button className="btn btn--sm" onClick={() => setSheetOpen(true)}>
            <Icon name="plus" size={16} /> {t('chores.addTask')}
          </button>
        }
      >
        {running.length === 0 && paused.length === 0 ? (
          <EmptyState icon="tasks" title={t('chores.noTasks')} hint={t('chores.noTasksHint')} />
        ) : (
          <ul className="list">
            {running.map((task) => (
              <TaskRow key={task.id} task={task} me={me} profiles={profiles} locale={locale} />
            ))}
            {paused.map((task) => (
              <TaskRow
                key={task.id}
                task={task}
                me={me}
                profiles={profiles}
                locale={locale}
                paused
              />
            ))}
          </ul>
        )}

        {doneTasks.length > 0 && (
          <details style={{ marginTop: 'var(--space-2)' }}>
            <summary style={{ cursor: 'pointer', fontSize: 13, fontWeight: 700 }}>
              {t('chores.doneCount', { n: doneTasks.length })}
            </summary>
            <ul className="list" style={{ marginTop: 'var(--space-2)' }}>
              {doneTasks.slice(0, 12).map((task) => (
                <li key={task.id} className="list__item">
                  <Icon name="check" size={16} />
                  <span className="grow" style={{ color: 'var(--muted)' }}>
                    {task.title}
                  </span>
                  <button
                    className="btn btn--ghost btn--sm"
                    onClick={() => patch('tasks', task.id, { status: 'todo', completedAt: undefined })}
                  >
                    {t('chores.undo')}
                  </button>
                </li>
              ))}
            </ul>
          </details>
        )}
      </Card>

      {/* Keyed on my answer for this round: the form seeds its state from the
          record, so it has to remount once the live query delivers one. */}
      <Fairness
        key={
          records.find(
            (r) => r.kind === 'fairness' && r.round === roundIdFor(new Date()) && r.profileId === me,
          )?.id ?? 'new'
        }
        me={me}
        profiles={profiles}
        records={records}
      />

      <p className="disclaimer">{t('chores.notInBackup')}</p>

      <NewChoreSheet
        open={sheetOpen}
        onClose={() => setSheetOpen(false)}
        me={me}
        profiles={profiles}
        suggestedId={suggestedId ?? me}
      />
    </div>
  )
}

function setDomainOwner(me: string, key: DomainKey, row: DomainRow | undefined, value: string) {
  if (row) return patchChoreRecord(row.id, { accountableProfileId: value })
  if (!value) return Promise.resolve()
  return addChoreRecord(me, 'C2_shared_ops', {
    kind: 'domain',
    domainKey: key,
    accountableProfileId: value,
  }).then(() => undefined)
}

/**
 * Capacity is C4_health: `sakit`, `hamil`, and `pemulihan` are health facts, so
 * the record starts private and only the owner can widen it. The partner sees
 * "not shared" rather than a guess.
 */
function CapacityForm({ me, record }: { me: string; record?: CapacityRow }) {
  const t = useT()
  const [state, setState] = useState<CapacityState>(record?.state ?? 'normal')
  const [until, setUntil] = useState(record?.until ?? '')
  const [note, setNote] = useState(record?.note ?? '')

  async function save() {
    const body = { state, until: until || undefined, note: note.trim() || undefined }
    if (record) await patchChoreRecord(record.id, body)
    else await addChoreRecord(me, 'C4_health', { kind: 'capacity', profileId: me, ...body })
  }

  return (
    <div className="stack stack--tight">
      <Field label={t('chores.capacityState')}>
        {(p) => (
          <select {...p} value={state} onChange={(e) => setState(e.target.value as CapacityState)}>
            {CAPACITY_STATES.map((s) => (
              <option key={s} value={s}>
                {t(`chores.cap.${s}` as const)}
              </option>
            ))}
          </select>
        )}
      </Field>
      <Field label={t('chores.capacityUntil')} hint={t('common.optional')}>
        {(p) => <input {...p} type="date" value={until} onChange={(e) => setUntil(e.target.value)} />}
      </Field>
      <Field label={t('chores.capacityNote')} hint={t('chores.capacityNoteHint')}>
        {(p) => <input {...p} type="text" value={note} onChange={(e) => setNote(e.target.value)} />}
      </Field>
      <button className="btn btn--block" onClick={save}>
        {t('chores.capacitySave')}
      </button>
      {record && (
        <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
          <VisibilityBadge visibility={record.visibility} />
          <Field label={t('chores.capacityWho')}>
            {(p) => (
              <select
                {...p}
                value={record.visibility}
                style={{ width: 'auto' }}
                onChange={(e) => setChoreVisibility(record.id, me, e.target.value as Visibility)}
              >
                {PARTNER_VISIBILITY_OPTIONS.map((v) => (
                  <option key={v} value={v}>
                    {t(`vis.${v}` as const)}
                  </option>
                ))}
              </select>
            )}
          </Field>
        </div>
      )}
    </div>
  )
}

/** Minimum Survival Mode. Pausing is a state, not a failure, and nothing is deleted. */
function SurvivalCard({
  me,
  survival,
  pausedCount,
}: {
  me: string
  survival?: SurvivalRow
  pausedCount: number
}) {
  const { t, locale } = useI18n()
  const [kept, setKept] = useState<DomainKey[]>([])

  function toggle(key: DomainKey) {
    setKept((prev) => (prev.includes(key) ? prev.filter((k) => k !== key) : [...prev, key]))
  }

  if (survival) {
    return (
      <Card title={t('chores.survival')} icon="repair" hint={t('chores.survivalHint')}>
        <p className="banner">
          {t('chores.survivalOn', { date: fmtDate(survival.startedAt, 'd MMM', locale) })}
        </p>
        <p className="card__hint">
          {survival.keptDomainKeys.length === 0
            ? t('chores.survivalNothingKept')
            : survival.keptDomainKeys.map((k) => t(`chores.domain.${k}` as const)).join(' · ')}
        </p>
        <p className="card__hint">{t('chores.survivalPaused', { n: pausedCount })}</p>
        <button
          className="btn btn--soft btn--block"
          onClick={() => patchChoreRecord(survival.id, { endedAt: new Date().toISOString() })}
        >
          {t('chores.survivalStop')}
        </button>
      </Card>
    )
  }

  return (
    <Card title={t('chores.survival')} icon="repair" hint={t('chores.survivalHint')}>
      <fieldset className="stack stack--tight" style={{ border: 0, padding: 0, margin: 0 }}>
        <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>
          {t('chores.survivalKeep')}
        </legend>
        <div className="row" style={{ gap: 8, flexWrap: 'wrap' }}>
          {/* Health is absent on purpose: `survivalPlan` keeps it running no
              matter what is ticked here, so offering a switch would lie. */}
          {DOMAIN_KEYS.filter((k) => k !== 'kesehatan').map((key) => (
            <label key={key} className="chip" style={{ cursor: 'pointer' }}>
              <input
                type="checkbox"
                checked={kept.includes(key)}
                onChange={() => toggle(key)}
                style={{ width: 'auto', minHeight: 0 }}
              />
              {t(`chores.domain.${key}` as const)}
            </label>
          ))}
        </div>
      </fieldset>
      <p className="card__hint">{t('chores.survivalKeepHint')}</p>
      <button
        className="btn btn--block"
        onClick={() =>
          addChoreRecord(me, 'C2_shared_ops', {
            kind: 'survival',
            startedAt: new Date().toISOString(),
            keptDomainKeys: kept,
          })
        }
      >
        {t('chores.survivalStart')}
      </button>
    </Card>
  )
}

function TaskRow({
  task,
  me,
  profiles,
  locale,
  paused,
}: {
  task: ChoreTask
  me: string
  profiles: Profile[]
  locale: 'id' | 'en'
  paused?: boolean
}) {
  const t = useT()
  const coverage = cycleCoverage(task.cycleOwners)
  const dod = dodState(task.dod)

  return (
    <li className="list__item" style={{ flexWrap: 'wrap' }}>
      <button
        className="btn btn--ghost btn--sm btn--icon"
        aria-label={t('chores.markDone', { name: task.title })}
        onClick={() => patch('tasks', task.id, { status: 'done', completedAt: new Date().toISOString() })}
      >
        <Icon name="check" size={16} />
      </button>
      <span className="grow stack stack--tight">
        <strong style={{ fontSize: 14 }}>{task.title}</strong>
        <span className="card__hint">
          {task.domainKey ? t(`chores.domain.${task.domainKey}` as const) : ''} ·{' '}
          {profiles.find((p) => p.id === task.accountableProfileId)?.displayName ?? t('chores.noOwner')}
          {task.dueDate ? ` · ${whenLabel(task.dueDate, t, locale)}` : ''}
        </span>
        <span className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
          <span className="chip">{t(dod)}</span>
          <span className="chip">
            {t('chores.coverage', { covered: coverage.covered.length, total: CYCLE_STEPS.length })}
          </span>
          {paused && <span className="chip chip--yellow">{t('chores.paused')}</span>}
        </span>
        <details>
          <summary style={{ cursor: 'pointer', fontSize: 13, fontWeight: 700 }}>
            {t('chores.details')}
          </summary>
          <TaskDetails task={task} profiles={profiles} />
        </details>
      </span>
      <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('tasks', task.id, me)}>
        <Icon name="close" size={16} label={t('common.deleteX', { name: task.title })} />
      </button>
    </li>
  )
}

/**
 * Definition of Done and the cycle, editable in place.
 *
 * The three DoD fields are uncontrolled and saved on blur: the live query would
 * otherwise fight every keystroke, and a chore's "done" is written once and
 * re-read many times.
 */
function TaskDetails({ task, profiles }: { task: ChoreTask; profiles: Profile[] }) {
  const t = useT()

  const saveDod = (field: 'minimum' | 'lengkap' | 'excluded', value: string) =>
    patch('tasks', task.id, { dod: { ...task.dod, [field]: value } })

  const saveStep = (step: CycleStep, value: string) =>
    patch('tasks', task.id, { cycleOwners: { ...task.cycleOwners, [step]: value } })

  return (
    <div className="stack stack--tight" style={{ marginTop: 'var(--space-2)' }}>
      <p className="card__hint">{t('chores.dodHint')}</p>
      {(['minimum', 'lengkap', 'excluded'] as const).map((field) => (
        <Field
          key={field}
          label={t(`chores.dod.${field}` as const)}
          hint={t(`chores.dod.${field}Hint` as const)}
        >
          {(p) => (
            <textarea
              {...p}
              rows={2}
              defaultValue={task.dod?.[field] ?? ''}
              onBlur={(e) => saveDod(field, e.target.value)}
            />
          )}
        </Field>
      ))}

      <p className="card__hint">{t('chores.cycleHint')}</p>
      {CYCLE_STEPS.map((step) => (
        <Field
          key={step}
          label={t(`chores.step.${step}` as const)}
          hint={t(`chores.step.${step}.desc` as const)}
        >
          {(p) => (
            <select
              {...p}
              value={task.cycleOwners?.[step] ?? ''}
              onChange={(e) => saveStep(step, e.target.value)}
            >
              <option value="">{t('chores.stepNobody')}</option>
              {profiles.map((x) => (
                <option key={x.id} value={x.id}>
                  {x.displayName}
                </option>
              ))}
            </select>
          )}
        </Field>
      ))}
    </div>
  )
}

function NewChoreSheet({
  open,
  onClose,
  me,
  profiles,
  suggestedId,
}: {
  open: boolean
  onClose: () => void
  me: string
  profiles: Profile[]
  suggestedId: string
}) {
  const t = useT()
  const [template, setTemplate] = useState<TemplateId | ''>('')
  const [title, setTitle] = useState('')
  const [domainKey, setDomainKey] = useState<DomainKey>('dapur')
  const [owner, setOwner] = useState(suggestedId)
  const [load, setLoad] = useState<MentalLoadType>('do')
  const [due, setDue] = useState('')

  function pickTemplate(value: string) {
    const tpl = CHORE_TEMPLATES.find((x) => x.id === value)
    setTemplate((tpl?.id ?? '') as TemplateId | '')
    if (!tpl) return
    setTitle(t(`chores.tpl.${tpl.id}` as const))
    setDomainKey(tpl.domainKey)
  }

  async function save() {
    if (!title.trim()) return
    const tpl = CHORE_TEMPLATES.find((x) => x.id === template)
    await db.tasks.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'task',
      title: title.trim(),
      accountableProfileId: owner,
      helperProfileIds: [],
      mentalLoadType: load,
      status: 'todo',
      ...(due ? { dueDate: due } : {}),
      domainKey,
      // A template seeds a draft "done" so the couple edits words rather than
      // starting from a blank box. Left empty for a hand-written chore, and the
      // cycle is always left empty — who carries which step is theirs to say.
      ...(tpl
        ? {
            dod: {
              minimum: t(`chores.tpl.${tpl.id}.min` as const),
              lengkap: t(`chores.tpl.${tpl.id}.full` as const),
              excluded: t(`chores.tpl.${tpl.id}.not` as const),
            },
          }
        : {}),
    } as never)
    setTitle('')
    setDue('')
    setTemplate('')
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('chores.newTask')}>
      <div className="stack">
        <Field label={t('chores.template')} hint={t('chores.templateHint')}>
          {(p) => (
            <select {...p} value={template} onChange={(e) => pickTemplate(e.target.value)}>
              <option value="">{t('chores.templateNone')}</option>
              {CHORE_TEMPLATES.map((tpl) => (
                <option key={tpl.id} value={tpl.id}>
                  {t(`chores.tpl.${tpl.id}` as const)}
                </option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('chores.taskTitle')}>
          {(p) => (
            <input
              {...p}
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder={t('chores.taskTitlePlaceholder')}
            />
          )}
        </Field>
        <Field label={t('chores.taskDomain')}>
          {(p) => (
            <select {...p} value={domainKey} onChange={(e) => setDomainKey(e.target.value as DomainKey)}>
              {DOMAIN_KEYS.map((k) => (
                <option key={k} value={k}>
                  {t(`chores.domain.${k}` as const)}
                </option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('chores.taskOwner')} hint={t('chores.taskOwnerHint')}>
          {(p) => (
            <select {...p} value={owner} onChange={(e) => setOwner(e.target.value)}>
              {profiles.map((x) => (
                <option key={x.id} value={x.id}>
                  {x.displayName}
                </option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('chores.loadKind')}>
          {(p) => (
            <select {...p} value={load} onChange={(e) => setLoad(e.target.value as MentalLoadType)}>
              {MENTAL_LOAD_TYPES.map((kind) => (
                <option key={kind} value={kind}>
                  {mentalLoadLabel(kind, t)}
                </option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('chores.due')} hint={t('common.optional')}>
          {(p) => <input {...p} type="date" value={due} onChange={(e) => setDue(e.target.value)} />}
        </Field>
        <button className="btn btn--block" onClick={save} disabled={!title.trim()}>
          {t('chores.saveTask')}
        </button>
      </div>
    </Sheet>
  )
}
