import type { DomainKey } from './choreMath'

/**
 * Indonesian household chores that reliably cause "I thought you did it".
 *
 * Templates carry a title, a domain, and a draft Definition of Done — and
 * deliberately no dates, no prices, and no recurrence. Vehicle tax and RT dues
 * have real deadlines that vary by household and by region; a default the app
 * invented would be a wrong fact with a consequence. The user sets the date.
 *
 * Copy lives in `messages.ts` under `chores.tpl.<id>` plus `.min` / `.full` /
 * `.not`, so the ids below double as message-key fragments.
 */
export const CHORE_TEMPLATES = [
  { id: 'galon', domainKey: 'dapur' },
  { id: 'lpg', domainKey: 'dapur' },
  { id: 'token_listrik', domainKey: 'rumah' },
  { id: 'iuran_rt', domainKey: 'rumah' },
  { id: 'sampah', domainKey: 'rumah' },
  { id: 'art_laundry', domainKey: 'laundry' },
  { id: 'servis_motor', domainKey: 'kendaraan' },
  { id: 'pajak_kendaraan', domainKey: 'kendaraan' },
  { id: 'mudik', domainKey: 'keluarga_besar' },
  { id: 'arisan', domainKey: 'keluarga_besar' },
] as const satisfies readonly { id: string; domainKey: DomainKey }[]

export type TemplateId = (typeof CHORE_TEMPLATES)[number]['id']
